  const recent=subs.slice(0,8);
  return <div className="dashboard-page simple-overview"><section className="overview-cards"><article><small>Total submittals</small><strong>{subs.length}</strong><span>{latest?`Latest: ${latest.project_name}`:"No packages yet"}</span></article><article><small>Completed</small><strong>{generated.length}</strong><span>Generated PDF packages</span></article><article><small>Draft / failed</small><strong>{drafts.length + failed.length}</strong><span>{drafts.length} drafts, {failed.length} failed</span></article><article><small>Products</small><strong>{products.length}</strong><span>{docs.length} stored documents</span></article></section><AnalyticsPanel user={user} subs={subs} onDownload={onDownload} onEditDraft={onEditDraft} onDelete={onDelete}/><section className="panel recent-panel"><div className="panel-title"><div><h2>Recent submittals</h2><p>Latest packages and draft actions</p></div></div><div className="table"><div className="tr th"><span>Submittal</span><span>Project / Details</span><span>Product name</span><span>Status</span><span></span></div>{recent.map(s=>{const canEdit=user.role==="admin"||user.role==="system_admin"||s.created_by?.id===user.id;const canDelete=canEdit;return <div className="tr" key={s.id}><span><b>{s.number}</b><small>Revision {s.revision}</small></span><span><b>{s.project_name}</b><small>Client: {s.client||"-"}</small><small>QTN REF: {s.project_number||"-"}</small></span><span className="product-name-cell">{s.products.map(product=>product.name).join(", ")||"-"}</span><span><i className={`status ${s.status}`}>{s.status}</i></span><span className="submittal-row-actions">{s.status==="generated"&&<button className="icon" onClick={()=>onDownload(s.id)} title="Download"><Download/></button>}{canEdit&&<button className="edit-product" onClick={()=>onEditDraft(s)} title={s.status==="generated"?"Edit generated submittal":"Edit draft"}>Edit</button>}{canDelete&&<button className="icon danger" onClick={()=>onDelete(s)} title="Delete submittal"><Trash2/></button>}</span></div>})}{!subs.length&&<div className="empty">No submittals yet. Create the first package from New submittal.</div>}</div></section></div>
