  const [selected,setSelected]=useState<string[]>([]),[attachments,setAttachments]=useState<PendingAttachment[]>([]),[attachmentCategory,setAttachmentCategory]=useState("Proposed Materials"),[customSectionName,setCustomSectionName]=useState(""),[orderKeys,setOrderKeys]=useState<string[]>([]),[sectionOrder,setSectionOrder]=useState<string[]>(packageSections),[workingDraftId,setWorkingDraftId]=useState(draft?.id||""),[busy,setBusy]=useState(false),[previewing,setPreviewing]=useState(false),[error,setError]=useState("");
  const attachmentSections=sectionOrder.filter(name=>!["Company Profile","Trade License"].includes(name));
  const selectedProducts=products.filter(product=>selected.includes(product.id));
  const mappedDocuments=Array.from(new Map(selectedProducts.flatMap(product=>product.documents).map(document=>[document.id,document])).values()).sort((a,b)=>a.sequence-b.sequence);
  const selectedCustomProductSections=Array.from(new Set(mappedDocuments.map(document=>document.category).filter(category=>category&&!packageSections.includes(category)&&category!=="Compliance"&&!["General","Product Document"].includes(category))));
  useEffect(()=>{setSectionOrder(current=>[...current,...selectedCustomProductSections.filter(section=>!current.includes(section))])},[selectedCustomProductSections.join("|")]);
  function documentSection(document:Doc){if(packageSections.includes(document.category))return document.category;if(document.category==="Compliance")return "General Compliance Statement";if(document.category&&!["General","Product Document"].includes(document.category))return document.category;const name=document.name.toLowerCase();const rules:[string,string][]=[["company profile","Company Profile"],["trade license","Trade License"],["proposed material","Proposed Materials"],["general compliance statement","General Compliance Statement"],["compliance statement","General Compliance Statement"],["compliance","General Compliance Statement"],["datasheet","Product Catalogues"],["data sheet","Product Catalogues"],["catalog","Product Catalogues"],["test","Test Reports"],["country of origin","Country of Origin"],["warranty","Draft Warranty Certificate"],["list of project","List of Previous Projects"],["project list","List of Previous Projects"],["previous project","List of Previous Projects"],["approval","Previous Approvals"]];return rules.find(([term])=>name.includes(term))?.[1]||"Proposed Materials"}
  const standardDocuments=docs.filter(document=>document.kind==="standard");
  const databaseDocuments=Array.from(new Map([...standardDocuments,...mappedDocuments].map(document=>[document.id,document])).values());
  const packageItems:PackageItem[]=[...databaseDocuments.map(document=>({key:`document:${document.id}`,name:document.file_name,section:documentSection(document),source:document.kind==="standard"?"Standard document":"Product document",documentId:document.id})),...attachments.map(item=>({key:`attachment:${item.id}`,name:item.name,section:item.category,source:item.saved?"Saved project attachment":"Project attachment",attachmentId:item.id}))];
